<script setup lang="ts">
import { computed,reactive,ref,watch } from 'vue';
import { Download,PackageCheck,FolderOpen,Cloud,Check,FileArchive,ChevronDown,Upload,HardDrive,Server,CloudUpload,ArrowRight,CircleCheck } from '@lucide/vue';
import { desk,safely,request,operation,apiPath,downloadDeployment,binary,loadProject,notify,openBrowse,openView } from './store';
import { bytes,when,newestReleases,type Data } from './model';
import { viewSections,sectionLabel } from './presentation';
import Segmented from './Segmented.vue';
const releases=computed(()=>newestReleases(desk.project?.releases));
const release=ref(''),platform=ref('windows-x64'),packageInput=ref<HTMLInputElement|null>(null),packageFile=ref<File|null>(null),plan=ref<Data|null>(null),agent=ref('0.1.2'),dropping=ref(false);
const program=reactive({sourceDirectory:'',version:'',launchPath:'DreamingFishUpdater.exe'});
const destination=ref(''),instance=ref('');const method=ref('export');
const hosting=reactive({outputDirectory:'',baseUrl:'',username:'',password:'',endpoint:'',region:'auto',bucket:'',prefix:'',accessKeyId:'',secretAccessKey:'',sessionToken:'',addressingStyle:'PATH',exportFirst:true});
const result=ref<Data|null>(null);
const programs=ref<Data[]>([]),currentProgram=ref('');
const platforms=[{id:'windows-x64',label:'Windows x64'},{id:'linux-x64',label:'Linux x64'}];
const methods=[{id:'export',title:'仅导出',detail:'生成静态目录，自行放到任意 HTTP 服务器。',icon:HardDrive},{id:'webdav',title:'WebDAV',detail:'导出后用 WebDAV 或 HTTP PUT 上传。',icon:Server},{id:'s3',title:'对象存储',detail:'导出后上传到兼容 S3 的存储桶。',icon:CloudUpload}];
const steps=computed(()=>[{title:'发布整合包',detail:releases.value.length?`当前 ${releases.value[0].displayVersion}`:'确认文件和维护设置已经发布。',done:releases.value.length>0,action:'查看改动',go:()=>openView('changes','changes')},{title:'发布玩家端程序',detail:currentProgram.value?`当前 ${currentProgram.value}`:'选择用于这个项目的更新器版本。',done:Boolean(currentProgram.value),action:'管理程序',go:()=>openView('delivery','programs')},{title:'制作部署包',detail:'下载 ZIP，接入启动器并完成一次启动测试。',done:false,action:'',go:null}]);
let platformRequest=0;
watch(()=>[desk.project,platform.value],()=>{const generation=++platformRequest;programs.value=[];currentProgram.value='';safely(async()=>{const details=await request(apiPath(`?platform=${encodeURIComponent(platform.value)}`));if(generation===platformRequest){programs.value=[...(details.playerPrograms||[])].sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt));currentProgram.value=details.currentProgramVersion||'';}});},{immediate:true});
watch(()=>desk.browseValues['deployment-output'],value=>{if(value)destination.value=value;});
watch(()=>desk.projectId,()=>{release.value='';plan.value=null;packageFile.value=null;result.value=null;});
function choosePackage(file:File|null){packageFile.value=file;plan.value=null;}
async function checkPackage(){if(!packageFile.value)return;await operation(async()=>{plan.value=await binary(apiPath(`/program-package?fileName=${encodeURIComponent(packageFile.value!.name)}`),packageFile.value!);},'正在上传并识别玩家端…');}
async function publishPackage(){await operation(async()=>{await request(apiPath('/program-package'),'POST',{id:plan.value?.id,minimumBootstrapVersion:agent.value});plan.value=null;packageFile.value=null;await loadProject();notify('玩家端程序已发布');},'正在发布玩家端…');}
async function publishDirectory(){await operation(async()=>{await request(apiPath('/programs'),'POST',{...program,platform:platform.value,minimumBootstrapVersion:agent.value});await loadProject();notify('玩家端程序已发布');});}
async function writeDeployment(){await operation(async()=>{result.value=await request(apiPath('/deployment'),'POST',{platform:platform.value,releaseId:release.value||releases.value[0]?.releaseId,outputDirectory:destination.value});notify('部署包已生成');},'正在写入部署包…');}
async function prepareInstance(){await operation(async()=>{result.value=await request(apiPath('/instance'),'POST',{platform:platform.value,releaseId:release.value||releases.value[0]?.releaseId,instanceDirectory:instance.value});notify('玩家实例已准备');},'正在准备实例…');}
async function distribute(){await operation(async()=>{result.value=await request(apiPath(method.value==='export'?'/distribution-export':method.value==='webdav'?'/distribution-webdav':'/distribution-s3'),'POST',hosting);hosting.password='';hosting.secretAccessKey='';hosting.sessionToken='';notify('静态分发内容已处理完成');},'正在准备分发…');}
</script>
<template>
 <div class="view delivery-view"><section class="stage">
  <header class="stage-toolbar"><Segmented class="section-tabs" :items="viewSections.delivery" :model-value="desk.section" label="发放" @update:model-value="safely(()=>openView('delivery',$event))"/><strong class="section-title">{{sectionLabel('delivery',desk.section)}}</strong><span class="toolbar-spacer"/>
   <template v-if="desk.section==='programs'"><span class="current-tag">当前 {{currentProgram||'未发布'}}</span><div class="select-capsule"><select v-model="platform" aria-label="程序平台"><option v-for="p in platforms" :key="p.id" :value="p.id">{{p.label}}</option></select><ChevronDown :size="13"/></div></template>
   <span v-else-if="desk.section==='hosting'" class="toolbar-note">让 HTTP、WebDAV 或对象存储提供玩家下载</span></header>

  <div v-if="desk.section==='deployment'" class="list-scroll"><div class="page-column">
   <section class="hero-card"><span class="hero-art"><FileArchive :size="40"/></span><div><span class="overline">首次发放</span><h2>把整合包交给玩家</h2><p>选择已经发布的版本，生成包含更新器与启动说明的部署包。</p><small>{{desk.project?.displayName}} · {{desk.project?.publicBaseUrl}}</small></div></section>
   <ol class="step-cards"><li v-for="(step,i) in steps" :key="i" :class="{done:step.done}"><span class="step-mark"><Check v-if="step.done" :size="14"/><template v-else>{{i+1}}</template></span><div><strong>{{step.title}}</strong><p>{{step.detail}}</p><button v-if="step.go" class="text-action" @click="safely(step.go)">{{step.action}}<ArrowRight :size="13"/></button></div></li></ol>
   <section class="form-card"><div class="form-grid"><label>整合包版本<div class="select-capsule wide"><select v-model="release"><option value="">最新发布 {{releases[0]?.displayVersion||''}}</option><option v-for="r in releases" :key="r.releaseId" :value="r.releaseId">{{r.displayVersion}} · #{{r.sequence}}</option></select><ChevronDown :size="13"/></div></label><div class="field"><span class="field-label">玩家平台</span><Segmented v-model="platform" :items="platforms" label="玩家平台"/></div></div>
    <div class="form-actions"><button class="accent large" :disabled="desk.busy||!releases.length||!currentProgram" @click="safely(()=>downloadDeployment(release||releases[0]?.releaseId,platform))"><Download :size="17"/>生成并下载部署 ZIP</button><span v-if="!currentProgram" class="field-help">先发布这个平台的玩家端程序。</span><span v-else class="field-help">生成后，按包内说明接入玩家的 PCL、HMCL 或其他启动器。</span></div></section>
   <details class="disclosure-card"><summary>写入管理端目录 / 准备现有实例</summary><label>部署包输出目录<div class="field-with-button"><input v-model="destination" placeholder="管理端所在电脑或服务器的目录"><button type="button" aria-label="浏览目录" @click="openBrowse('directory','deployment-output',destination)"><FolderOpen :size="16"/></button></div></label><button :disabled="!destination||desk.busy" @click="safely(writeDeployment)">写入部署包</button><label class="spaced">现有实例目录<input v-model="instance" placeholder="包含 mods、config 的玩家实例目录"></label><button :disabled="!instance||desk.busy" @click="safely(prepareInstance)">准备此实例</button></details>
   <p v-if="result" class="notice-card success"><CircleCheck :size="17"/>{{result.outputDirectory||result.instanceDirectory||'处理完成'}}</p>
  </div></div>

  <div v-else-if="desk.section==='programs'" class="list-scroll"><div class="page-column">
   <div class="drop-card" :class="{dropping}" @dragover.prevent="dropping=true" @dragleave="dropping=false" @drop.prevent="dropping=false;choosePackage($event.dataTransfer?.files[0]||null)"><span class="hero-art small"><FileArchive :size="28"/></span><strong>{{packageFile?.name||'选择或拖入玩家端发行 ZIP'}}</strong><p>{{packageFile?bytes(packageFile.size):'保留原发行包结构，系统会识别平台和版本。'}}</p><div class="drop-actions"><button @click="packageInput?.click()"><Upload :size="15"/>选择 ZIP</button><button class="accent" :disabled="!packageFile||desk.busy" @click="safely(checkPackage)">检查发行包</button></div><input ref="packageInput" type="file" accept=".zip" hidden @change="choosePackage(($event.target as HTMLInputElement).files?.[0]||null)"></div>
   <div v-if="plan" class="notice-card" :class="plan.publishable?'success':'warning'"><PackageCheck :size="20"/><div><strong>已识别 {{plan.version}} · {{plan.platform}}</strong><p>{{plan.problem||plan.launcher||plan.sourceRelative||''}}</p></div><button class="accent" :disabled="desk.busy||!plan.publishable" @click="safely(publishPackage)">确认发布</button></div>
   <section class="list-card"><header><strong>已发布的程序</strong><span>{{platforms.find(p=>p.id===platform)?.label}} · {{programs.length}} 个</span></header><div v-for="(p,i) in programs" :key="p.manifestSha256" class="list-card-row"><span class="release-dot" :class="{latest:p.version===currentProgram}"/><strong>{{p.version}}</strong><span class="subtle">{{p.platform}}</span><span class="subtle">{{when(p.createdAt)}}</span><span v-if="p.version===currentProgram" class="current-tag">当前</span></div><p v-if="!programs.length" class="card-note">还没有发布这个平台的玩家端程序。</p></section>
   <details class="disclosure-card"><summary>从已有程序目录发布</summary><div class="form-grid"><label>程序目录<input v-model="program.sourceDirectory"></label><label>程序版本<input v-model="program.version"></label><label>启动文件<input v-model="program.launchPath"></label><label>最低 Agent 版本<input v-model="agent"></label></div><button :disabled="!program.sourceDirectory||desk.busy" @click="safely(publishDirectory)">发布目录中的程序</button></details>
  </div></div>

  <div v-else class="list-scroll"><div class="page-column">
   <div class="choice-cards" role="radiogroup" aria-label="托管方式"><button v-for="item in methods" :key="item.id" role="radio" :aria-checked="method===item.id" :class="{active:method===item.id}" @click="method=item.id"><span class="choice-icon"><component :is="item.icon" :size="20"/></span><strong>{{item.title}}</strong><small>{{item.detail}}</small><span class="option-radio"/></button></div>
   <form class="form-card" @submit.prevent="safely(distribute)"><label>静态目录<input v-model="hosting.outputDirectory" placeholder="管理端生成静态文件的目录" required></label>
    <template v-if="method==='webdav'"><label>WebDAV / HTTP PUT 地址<input v-model="hosting.baseUrl" type="url" required></label><div class="form-grid"><label>用户名<input v-model="hosting.username" autocomplete="off"></label><label>密码<input v-model="hosting.password" type="password" autocomplete="off"></label></div></template>
    <template v-if="method==='s3'"><label>S3 Endpoint<input v-model="hosting.endpoint" type="url" required></label><div class="form-grid"><label>Region<input v-model="hosting.region" required></label><label>Bucket<input v-model="hosting.bucket" required></label><label>目录前缀<input v-model="hosting.prefix"></label><label>寻址方式<div class="select-capsule wide"><select v-model="hosting.addressingStyle"><option value="PATH">Path</option><option value="VIRTUAL_HOST">Virtual hosted</option></select><ChevronDown :size="13"/></div></label><label>Access Key ID<input v-model="hosting.accessKeyId" autocomplete="off" required></label><label>Secret Access Key<input v-model="hosting.secretAccessKey" type="password" autocomplete="off" required></label></div><details class="disclosure-inline"><summary>临时会话令牌</summary><input v-model="hosting.sessionToken" type="password" autocomplete="off" aria-label="临时会话令牌"></details></template>
    <div class="form-actions"><button class="accent large" :disabled="desk.busy"><Cloud :size="16"/>{{method==='export'?'导出静态内容':'导出并上传'}}</button><span class="field-help">账户和密钥只用于这次上传，不会保存。</span></div></form>
   <div v-if="result" class="notice-card success"><CircleCheck :size="20"/><div><strong>处理完成</strong><p>{{result.outputDirectory||result.destination}}</p><small>{{result.objectCount||result.fileCount||result.completedFileCount||''}} 项 · {{bytes(result.totalObjectBytes||result.totalBytes||0)}}</small></div></div>
  </div></div>
 </section></div>
</template>
